process = vgroup("SOscillator",environment{declare name 		"os.osc";
declare version 	"1.0";
declare author 		"Grame";
declare license 	"BSD";
declare copyright 	"(c)GRAME 2009";

//-----------------------------------------------
// 			Sinusoidal Oscillator
//-----------------------------------------------

/* =========== DESCRIPTION =============

- Simple sine wave oscillator
- Left = low frequencies
- Right = high frequencies
- Front = around 300Hz
- Rocking = from low to high
*/ 

import("stdfaust.lib");

freq 			= hslider("Frequency [unit:Hz] [acc:0 1 -10 0 10]", 300, 70, 2400, 0.01):si.smooth(0.999);
process 		= vgroup("Oscillator", os.osc(freq));

}.process);

process = vgroup("LFO",environment{declare name "LFO";
declare author "GRAME";
import("stdfaust.lib");

/* =============== DESCRIPTION ================

- Low frequency oscillator, bipolar output in [-1, 1]: a modulation source
- Shape: 0 sine, 1 triangle, 2 square, 3 sawtooth
- Connect the output to a widget of another module and choose "modulate" in the palette

*/

process = vgroup("LFO", select4(shape, os.osc(rate), os.lf_triangle(rate), os.lf_squarewave(rate), os.lf_saw(rate)));

rate = hslider("Rate[unit:Hz][scale:log]", 1, 0.01, 20, 0.01);
shape = hslider("Shape (sine, triangle, square, saw)", 0, 0, 3, 1);
select4(s, a, b, c, d) = select2(s >= 2, select2(s >= 1, a, b), select2(s >= 3, c, d));
}.process);

process = vgroup("Clock",environment{declare name "Clock";
declare author "GRAME";
import("stdfaust.lib");

/* =============== DESCRIPTION ================

- Gate signal: 1 during a fraction of each period, 0 otherwise
- Tempo in beats per minute, Length: fraction of the period where the gate is on
- To trigger envelopes (ADSR) or drive buttons ("drive" in the palette)

*/

process = vgroup("Clock", (os.phasor(1, tempo / 60) < length) : float);

tempo = hslider("Tempo[unit:BPM]", 120, 20, 600, 1);
length = hslider("Length", 0.5, 0.01, 0.99, 0.01);
}.process);

process = vgroup("ADSR",environment{declare name "ADSR";
declare author "GRAME";
import("stdfaust.lib");

/* =============== DESCRIPTION ================

- Envelope generator, unipolar output in [0, 1]
- Triggered by its input (a gate: on while above 0, e.g. from Clock) or by its Gate button
- To shape a level: connect the output to a gain and choose "scale" in the palette

*/

process = vgroup("ADSR", _ > 0 : max(button("Gate")) : en.adsr(a, d, s, r));

a = hslider("[1]Attack[unit:s]", 0.01, 0.001, 2, 0.001);
d = hslider("[2]Decay[unit:s]", 0.2, 0.001, 2, 0.001);
s = hslider("[3]Sustain", 0.5, 0, 1, 0.01);
r = hslider("[4]Release[unit:s]", 0.3, 0.001, 5, 0.001);
}.process);

process = vgroup("Volume",environment{declare name "Volume";
declare author "GRAME";

/* ========== DESCRITPION ===========

- Simple volume slider
- Head = Silence
- Bottom = Max volume

*/

import("stdfaust.lib");

process = par(i,2,*(hslider("Volume[acc:1 0 -10 0 10]", 0.75, 0, 1, 0.01):si.smooth(0.999)));
}.process);
